testbench_sv:
`timescale 1ns/1ps
module tb;
  reg clk, reset;
  wire [3:0] count;

  counter4 dut (.clk(clk), .reset(reset), .count(count));

  initial clk = 0;
  always #5 clk = ~clk;

  initial begin
    #10000 $display("##TIMEOUT");
    $finish;
  end

  initial begin
    reset = 1;
    @(posedge clk); #1;
    if (count === 4'd0) $display("##TEST T1 PASS exp=0 got=%0d", count);
    else $display("##TEST T1 FAIL exp=0 got=%0d", count);

    reset = 0;
    @(posedge clk); #1;
    if (count === 4'd1) $display("##TEST T3 PASS exp=1 got=%0d", count);
    else $display("##TEST T3 FAIL exp=1 got=%0d", count);

    reset = 1; #1;
    if (count === 4'd1) $display("##TEST T2 PASS exp=1 got=%0d", count);
    else $display("##TEST T2 FAIL exp=1 got=%0d", count);

    @(posedge clk); #1;
    if (count === 4'd0) $display("##TEST T6 PASS exp=0 got=%0d", count);
    else $display("##TEST T6 FAIL exp=0 got=%0d", count);

    reset = 0;
    repeat (5) @(posedge clk); #1;
    if (count === 4'd5) $display("##TEST T4 PASS exp=5 got=%0d", count);
    else $display("##TEST T4 FAIL exp=5 got=%0d", count);

    repeat (10) @(posedge clk);
    @(posedge clk); #1;
    if (count === 4'd0) $display("##TEST T5 PASS exp=0 got=%0d", count);
    else $display("##TEST T5 FAIL exp=0 got=%0d", count);

    $display("##DONE");
    $finish;
  end
endmodule

reference_sv:
module counter4 (
    input  logic       clk,
    input  logic       reset,
    output logic [3:0] count
);
    always @(posedge clk) begin
        if (reset)
            count <= 4'd0;
        else
            count <= count + 4'd1;
    end
endmodule
